def solve_anti_diagonal_connection(grid):
    rows = len(grid)
    cols = len(grid[0])

    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    ones = [(r,c) for r in range(rows) for c in range(cols) if grid[r][c] == 1]

    # Group by anti-diagonal sum
    groups = {}
    for r, c in ones:
        s = r + c
        if s not in groups:
            groups[s] = []
        groups[s].append((r, c))

    for s, positions in groups.items():
        if len(positions) >= 2:
            min_r = min(p[0] for p in positions)
            max_r = max(p[0] for p in positions)
            for r in range(min_r, max_r + 1):
